// lib/feed/gtin-cdon.ts
//
// EAN/GTIN PER VARIANT UR CDON (Leonards lista 2026-11-14, inläst 2026-11-15).
// Används i Prisjakt- och PriceRunner-flödena, ALDRIG i Google-flödet (regeln och
// sammanslagningen med dealproffsens koder står i lib/feed/gtin.ts).
//
// VAR KODERNA KOMMER IFRÅN. Leonard slog upp varje variant hos CDON, där samma
// artikel säljs av leverantörens egen butik (Aosom) eller av en återförsäljare
// (VEVOR-varor hos Bonideco). Paret är gjort på leverantörens artikelnummer. En
// rad är med bara när CDON:s artikelnummer är vårt ("Ja: samma nr") och statusen
// är "Hittad".
//
// UTANFÖR: VEVOR-varor hos Bancros (koderna kommer från 53 olika företagsprefix
// och ser köpta ut), rader som hittades hos Kaufland, rader märkta "Osäker",
// koder med fel kontrollsiffra, varianter med två olika koder och koder som står
// på två varianter (alla bort). 12-siffriga UPC skrivs som GTIN-13 med en
// inledande nolla. Kontorsstolen 3921d391-… är utanför (se prisjakt-gtin.ts).
//
// ⚠️ Aosom levererar white label och lämnar inte ut EAN (svar 2026-09-15).
// Koderna är dem Aosom själv använder i sin CDON-butik. Vi använder dem bara för
// att jämförelsesajterna ska koppla erbjudandet till rätt produktsida. Google
// stämmer av GTIN mot märket, och där är märket Fyndplats: därför aldrig där.
//
// ⚠️ Följ upp i Prisjakts Business Center: kopplas varorna till rätt produktsida?
// En kod som hamnar på fel sida tas bort här, som kontorsstolen 2026-10-28.
//
// Genererad, en post per rad: "variant-id": "GTIN-13". Inga titlar,
// artikelnummer eller adresser: repot är publikt, och listan är konfidentiell
// och ligger aldrig i repot (prov i gtin-cdon.test.ts).

